/* Isolated design simulation: no fetch, production endpoints, storage, or providers. */
const F=window.fixture, P=new URLSearchParams(location.search);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const direction=['utility','editorial','focus'].includes(P.get('direction'))?P.get('direction'):'utility';
let view=location.hash.slice(1)||'opportunities', state=P.get('state')||'normal', question=0, help='writing', dirty=false, savedAnswer=F.answer, answer=F.answer, letter=F.letter, selectedJob=view==='history'?3:0;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const link=(v,t,cls='')=>`<a href="#${v}" class="${cls}">${t}</a>`;
const btn=(id,t,cls='')=>`<button type="button" data-action="${id}" class="${cls}">${t}</button>`;
const field=(id,label,val='',type='text')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(val)}"></div>`;
const status=(t,c='')=>`<span class="status ${c}">${t}</span>`;
const notice=(title,text,c='')=>`<div class="notice ${c}"><strong>${title}</strong><p>${text}</p></div>`;
const heading=(title,desc='',action='')=>`<header class="heading"><div><h1 tabindex="-1">${title}</h1>${desc?`<p>${desc}</p>`:''}</div><div class="actions">${action}</div></header>`;
const groups=[['Work',[['opportunities','Opportunities'],['applications','Applications']]],['Your materials',[['documents','Documents'],['candidate','Candidate Profile'],['library','Answer Library'],['evidence','Career Evidence']]],['Preferences',[['ai','AI Connections'],['utilities','Utilities']]]];
const jobViews=['overview','prepare','answers','letter','transfer','history'];
const icon='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 9h8M8 13h8M8 17h5"/></svg>';
function navIcon(v){const paths={opportunities:'M4 7h16v14H4zM8 7V3h8v4',applications:'m4 12 5 5L20 5',documents:'M5 3h10l4 4v14H5zM14 3v5h5',candidate:'M8 7a4 4 0 1 0 8 0 4 4 0 1 0-8 0M4 21v-3a8 8 0 0 1 16 0v3',library:'M4 4h7v16H4zM14 4h6v16h-6z',evidence:'M4 20V4m0 16h16M7 15l4-5 4 2 5-7',ai:'m12 3 2 6 6 3-6 2-2 7-2-7-6-2 6-3z',utilities:'M4 7h16M4 17h16M8 4v6m8 4v6'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[v]}"/></svg>`}
function navigation(){return groups.map(([g,items])=>`<div class="nav-group"><small>${g}</small>${items.map(([v,t])=>`<a class="nav-link" href="#${v}" ${v===view||(v==='opportunities'&&jobViews.includes(view))?'aria-current="page"':''}>${navIcon(v)}${t}</a>`).join('')}</div>`).join('')}
function jobHeader(){const j=F.jobs[selectedJob];return `<div class="job-heading"><div><div class="eyebrow">${esc(j.company)}</div><h1 tabindex="-1">${esc(j.title)}</h1><p class="meta">${j.priority==='high'?'High priority · ':''}$108,000–$132,000 · Saved posting</p></div><div class="actions">${link('opportunities','All opportunities','button quiet')}</div></div><nav class="job-tabs" aria-label="Job workspace">${[['overview','Overview'],['prepare','Prepare'],['answers','Answers'],['letter','Cover letter'],['history','History']].map(([v,t])=>`<a href="#${v}" ${view===v||view==='transfer'&&v==='prepare'?'aria-current="page"':''}>${t}</a>`).join('')}</nav>`}
function opportunities(){if(state==='empty')return heading('Opportunities')+`<section class="empty"><div class="eyebrow">Your first application</div><h2>Start with a job you want.</h2><p>Save the posting here. Add your resume and candidate details when you’re ready to prepare it. AI is optional.</p>${btn('add','Add opportunity','primary')}</section><div class="row"><div><strong>Already have your materials?</strong><small>Import a resume or review your contact information.</small></div>${link('documents','Documents')}${link('candidate','Candidate Profile')}</div>`;
return heading('Opportunities','',btn('add','+ Add opportunity','primary'))+`<div class="queue-summary"><span><strong>5</strong> to work on</span><span><strong>1</strong> recorded today</span><span><strong>1</strong> recorded overall</span></div><div class="next-job"><div><div class="eyebrow">Suggested next · high priority, marked ready by you</div><h2>Implementation Engineer, Secure Data Exchange</h2><p>Foster Bend Digital Research Cooperative · Resume selected</p></div><a href="#prepare" data-job="5" class="button primary">Review preparation →</a></div><div class="focus-intro"><h2>Choose one application to work on</h2><p class="meta">Your other opportunities remain available here.</p></div><div class="filters"><div class="field"><label for="search">Search opportunities</label><input id="search" type="search" placeholder="Role or company"></div><div class="field"><label for="stage">Stage</label><select id="stage"><option value="active">Still to work on</option><option value="all">All stages</option><option value="ready">Marked ready</option><option value="applied">Recorded</option><option value="closed">Closed</option></select></div><div class="field sort"><label for="sort">Order</label><select id="sort"><option value="priority">Priority & next steps</option><option value="company">Company A–Z</option><option value="newest">Recently saved</option></select></div></div><div class="jobs" id="job-list"></div><div class="form-actions">${btn('bulk','Select jobs','quiet')}<span class="meta">7 saved in total · “Marked ready” is your planning label.</span></div><details><summary>Progress details</summary><p class="meta">1 of 6 active or recorded opportunities has a local submission record. Closed jobs are excluded. Adding opportunities changes this denominator.</p><progress value="1" max="6" aria-label="Recorded opportunities">1 of 6</progress></details>`}
function jobRows(){let list=F.jobs.filter(j=>{const s=$('#stage')?.value||'active';return(s==='all'||s==='active'&&!['applied','closed'].includes(j.stage)||j.stage===s)&&`${j.company} ${j.title}`.toLowerCase().includes(($('#search')?.value||'').toLowerCase())});const order=$('#sort')?.value;if(order==='company')list.sort((a,b)=>a.company.localeCompare(b.company));else if(order==='newest')list.sort((a,b)=>b.id-a.id);else list.sort((a,b)=>(a.priority==='high'?-1:0)-(b.priority==='high'?-1:0)||b.id-a.id);$('#job-list').innerHTML=list.length?list.map(j=>`<article class="job-row"><input class="bulk-check" type="checkbox" aria-label="Select ${esc(j.company)}" ${j.stage==='applied'?'disabled':''}><div><p class="company">${esc(j.company)}${j.priority==='high'?'<span class="priority">High priority</span>':''}</p><h3><a href="#${j.stage==='applied'?'history':'overview'}" data-job="${j.id-1}">${esc(j.title)}</a></h3><small>${j.resume?'Resume selected':'No resume selected'} · ${j.stage==='ready'?'Marked ready by you':j.stage==='applied'?'Submission recorded':j.stage==='closed'?'Closed':'Review'}</small></div><div class="row-state">${j.stage==='applied'?'Review history':j.resume?'Review and prepare':'Choose a resume'}</div><a class="open-link" href="#${j.stage==='applied'?'history':'prepare'}" data-job="${j.id-1}" aria-label="Open ${esc(j.company)}">→</a></article>`).join(''):`<section class="empty"><h2>No matches</h2><p>Try another company or clear your filters.</p>${btn('clear','Clear filters')}</section>`}
function overview(){return jobHeader()+`<div class="overview-grid"><section><div class="section-head"><h2>About the role</h2>${btn('edit-job','Edit details','quiet')}</div><div class="reading">${esc(F.description)}</div><div class="form-actions">${link('prepare','Prepare application →','button primary')}${btn('posting','Open posting ↗')}</div></section><aside><dl class="facts"><div><dt>Planning stage</dt><dd>Marked ready by you</dd></div><div><dt>Selected document</dt><dd class="filename">${F.resume}</dd></div><div><dt>Compensation source</dt><dd>Manually entered</dd></div><div><dt>Posting details</dt><dd>Saved locally; availability unverified</dd></div></dl><details><summary>Posting source</summary><p class="meta">jobs.example.test/northstar · Refreshing preserves manual edits.</p>${btn('refresh','Refresh posting')}</details><details><summary>Delete job</summary><p class="meta">Permanent deletion requires explicit confirmation. Document library copies remain.</p>${btn('delete-job','Review deletion','danger')}</details></aside></div>`}
function prepare(){const missing=state==='missing', restart=state==='restart', partial=state==='partial', active=state==='active';return jobHeader()+heading('Prepare this application','Saved materials are separate from the employer form.',btn('brief','Copy application brief'))+(restart?notice('The previous employer browser is no longer connected','Your saved materials remain. Browser-only edits, sign-in, and attachments have not been restored. Open without filling, then inspect the current form.'):partial?notice('Check one uncertain field on the employer form','The technical issue answer could not be verified. Completed transfers will not be replayed.'):missing?notice('Choose an available resume','The selected document is missing. You can repair your selection or continue manually on the employer site.'): '')+`<div class="readiness"><section><div class="material-row"><span class="number">01</span><div><h3>Resume</h3><p class="filename">${missing?'Selected file unavailable':F.resume}</p><details><summary>${missing?'Choose another resume':'Change selected resume'}</summary><div class="field"><label for="resume">Document</label><select id="resume"><option>${F.resume}</option><option>Alex_Morgan_Implementation_v2.docx</option></select></div>${btn('save-resume','Save resume')}</details></div>${status(missing?'Missing':'Selected',missing?'warn':'good')}</div><div class="material-row"><span class="number">02</span><div><h3>Candidate Profile</h3><p>${missing?'Not yet approved':'Contact details approved by you'}</p>${link('candidate',missing?'Review profile':'Review facts')}</div>${status(missing?'Draft':'Approved',missing?'':'good')}</div><div class="material-row"><span class="number">03</span><div><h3>Application answers</h3><p>${state==='no-questions'?'No questions discovered yet':'2 need your input · 2 saved locally'}</p>${link('answers',state==='no-questions'?'Discover questions':'Answer questions →')}</div>${status('Local')}</div><div class="material-row"><span class="number">04</span><div><h3>Cover letter</h3><p>${state==='no-letter'?'Optional · no saved draft':'Saved draft · edit before using'}</p>${link('letter',state==='no-letter'?'Generate a letter':'Edit saved letter')}</div>${status('Optional')}</div><p class="meta section">${state==='no-questions'?'No inspection is available.':'Early question preview is partial; later or conditional questions may be missing.'} Work authorization and consent stay on the employer site.</p></section><aside class="browser-card"><div class="eyebrow">Employer application</div><h3>${restart?'Start a new browser':active?'Browser open':partial?'Manual review needed':'Review before filling'}</h3><p>${restart?'Open without sending material.':active?'Keep the existing employer window open while preparing new material.':partial?'Inspect the uncertain field in the existing window.':'Choose what to send by reviewing the exact saved material.'}</p>${link('transfer',restart?'Review recovery':active?'Review new material':partial?'Review transfer results':'Review transfer →','button primary')}</aside></div><details><summary>More copy options</summary><p class="meta">The brief contains saved job details and question wording. It excludes profile values and saved or unsaved answers.</p><div class="actions">${btn('brief','Copy questions')}${btn('brief','Copy job details')}</div></details><details><summary>Already submitted on the employer site?</summary><p class="meta">Record your confirmation locally. YourMove cannot verify employer receipt.</p>${btn('record','Record completed application')}</details>`}
const questions=[F.question,'Why are you interested in this role?','Describe your experience with API troubleshooting.','What would you like us to know about your approach to documentation?'];
function answers(){return jobHeader()+`<section class="writer"><div class="writing-header"><div class="field"><label for="question">Application answers · ${state==='early'?'Early preview':'Current browser observation'}</label><select id="question">${questions.map((q,i)=>`<option value="${i}" ${i===question?'selected':''}>${i+1} of 4 · ${i===0?'Technical investigation':i===1?'Interest in the role':i===2?'API troubleshooting':'Documentation'}${i>1?' · Saved':''}</option>`).join('')}</select></div>${btn('focus','Focus writing','quiet')}</div><p class="meta">Required · ${state==='early'?'Early answers need explicit review before use in a live form.':'Partial inspection; later questions may be missing.'}</p><h2 class="question-label" id="prompt">${questions[question]}</h2><div class="field"><label for="answer">Your answer</label><textarea id="answer" spellcheck="true">${esc(answer)}</textarea></div><div class="savebar"><span class="form-status" id="save-status" role="status">${dirty?'Unsaved changes':'Saved locally · not transferred'}</span><div class="actions">${btn('previous','← Previous')}${btn('save-answer','Save answer locally','primary')}${btn('next','Next →')}</div></div><details class="help" ${P.get('help')==='open'?'open':''}><summary>Help me answer</summary><div class="help-nav">${[['writing','Previous writing'],['experience','Career Evidence'],['ai','Draft with AI']].map(([k,t])=>`<button data-help="${k}" aria-pressed="${help===k}">${t}</button>`).join('')}</div><div class="help-content" id="help-content">${helpContent()}</div></details><details><summary>Keep this answer for future writing</summary><p class="meta">Save the answer locally first, then keep an independent copy with this question and source context.</p>${btn('promote','Save to Answer Library')}</details>${state==='early'?`<details><summary>Review against the live form</summary><p>Early and live questions remain separate. Compare exact wording and current identity before accepting.</p>${btn('accept','Use prepared answer for this question')}</details>`:''}</section>`}
function helpContent(){if(help==='writing')return `<div class="source-preview"><span class="eyebrow">Answer Library · Cedar Systems</span><h3>Tell us about a challenging support incident.</h3><p class="meta">A writing example, not verified facts about this application.</p><details><summary>Read complete example</summary><p class="source-text">${esc(F.answer)}</p></details>${btn('use-writing','Use as starting point')}</div>${link('library','Browse Answer Library →')}`;if(help==='experience')return `<div class="source-preview"><span class="eyebrow">Reviewed by you</span><h3>Investigating intermittent API timeouts</h3><p>Compared request logs with deployment times; reproduced the issue in a test environment.</p><p class="meta">Outcome: long-term impact unknown. No metric inferred.</p><details><summary>Read situation, actions, and source</summary><p class="source-text">${esc(F.answer)}</p></details></div>${link('evidence','Review Career Evidence →')}`;return `<p>Choose factual sources. Nothing is selected automatically.</p><label class="check"><input id="source-evidence" type="checkbox">Reviewed experience: API timeouts</label><label class="check"><input id="source-resume" type="checkbox">Readable application resume excerpt</label><div class="fields"><div class="field"><label for="provider">Provider</label><select id="provider"><option>OpenAI API · external service</option><option>Ollama · on this Mac</option></select></div>${field('model','Model','configured-model')}</div><p class="meta">Provider labels and model here are synthetic. Production checks the selected configuration.</p>${btn('review-ai','Review selected sources')}${link('ai','AI Connections →')}`}
function coverLetter(){return jobHeader()+heading('Cover letter',state==='no-letter'?'Generate a draft, then edit it here.':'Saved draft 1 · Selected for this job',btn('focus','Focus writing','quiet'))+`<section class="writer">${state==='no-letter'?notice('Generation needs readable source documents','Use a master resume, an application resume, and the saved job description. AI is optional for the rest of YourMove.','info'):`<div class="field"><label for="letter">Letter text</label><textarea id="letter" class="letter" spellcheck="true">${esc(letter)}</textarea></div><div class="savebar"><span id="save-status" class="form-status" role="status">Saved locally · downloads use saved text</span><div class="actions">${btn('download','Export saved PDF')}${btn('save-letter','Save my edits','primary')}</div></div><p class="meta">Return to transfer review before sending a saved letter. Existing or uncertain employer attachments are preserved.</p><div class="form-actions">${link('transfer','Review saved letter for transfer →')}</div>`}<details ${state==='no-letter'?'open':''}><summary>${state==='no-letter'?'Generate a cover letter':'Write another version'}</summary><div class="fields"><div class="field"><label for="letter-provider">Provider</label><select id="letter-provider"><option>Ollama · on this Mac</option><option>OpenAI API · external service</option></select></div>${field('letter-model','Model','installed-model')}<div class="field full"><label for="letter-source">Resume to emphasize</label><select id="letter-source"><option>${F.resume}</option></select><small>This writing source does not change the selected employer attachment.</small></div></div><details><summary>Review source evidence</summary><p class="source-text">Master resume: Alex Morgan — support engineering, APIs, SQL.\nApplication resume: clinical support emphasis.\nJob description: ${esc(F.description)}</p></details><label class="check"><input id="letter-consent" type="checkbox">Use my saved job description and resume evidence to write this draft. Nonlocal providers receive text outside my device.</label><div class="form-actions">${btn('generate-letter','Generate a new draft','primary')}</div></details><details><summary>Earlier versions and source context</summary><p class="meta">Draft 1 · Ollama / installed-model · October 22, 2026. Source identities stay attached to each version.</p>${btn('old-letter','Open saved version')}</details></section>`}
function transfer(){return jobHeader()+heading(state==='restart'?'Recover this application':'Review employer transfer','Only the saved material listed here is in scope.')+(state==='restart'?notice('The old browser session cannot be restored','Your saved answers, documents, and letters remain. Browser-only entries and attachment state are unknown.')+btn('open-without','Open browser without filling','primary'):state==='partial'?notice('Technical investigation answer: uncertain','Check this field in the employer browser. YourMove will not replay an uncertain transfer.')+`<div class="row"><div><strong>Resume</strong><small>File selected in Chromium; employer acceptance unverified.</small></div>${status('Review on site')}</div><div class="row"><div><strong>Contact information</strong><small>Supported fields observed as filled.</small></div>${status('Observed','good')}</div>`:`<section class="writer"><div class="row"><div><h3>Resume to attach</h3><small class="filename">${F.resume}</small></div>${status('Saved','good')}</div><div class="row"><div><h3>Approved contacts</h3><p>Alex Morgan · alex@example.test · +1 202 555 0142</p></div></div><details open><summary>Saved answer · technical investigation</summary><p class="source-text">${esc(savedAnswer)}</p></details><details><summary>Exact saved cover letter</summary><p class="source-text">${esc(F.letter)}</p></details><div class="field"><label for="letter-mode">Cover-letter control</label><select id="letter-mode"><option>Attach saved letter as PDF</option><option>Fill explicitly labeled cover-letter text field</option></select></div>${notice('The employer may receive this material immediately','Existing manual entries and attachments are preserved. Review all results and submit personally.','info')}${btn('transfer','Authorize transfer to employer browser','primary')}<p class="meta section">This simulation opens no browser and sends nothing. Production revalidates every item independently.</p></section>`)+`<details><summary>Browser details and troubleshooting</summary><p class="meta">Recheck reads the current form. Reopening can lose browser-only work and needs confirmation.</p><div class="actions">${btn('recheck','Recheck current form')}${btn('restart','Review reopening')}</div></details><details><summary>Finished on the employer site?</summary>${btn('record','Record completed application')}</details>`}
function documents(){return heading('Documents','PDF and DOCX resumes stored on this Mac.',btn('import','Import resume','primary'))+(state==='empty'?`<section class="empty"><h2>Bring your first resume.</h2><p>Import an application resume first. A master resume is a separate career source for generating letters.</p>${btn('import','Choose PDF or DOCX','primary')}</section>`:`<div class="section-head"><span class="meta">3 current documents · 1 archived version</span>${link('utilities','Role families →')}</div>${[F.resume,'Alex_Morgan_Master_Career_History.docx','Alex_Morgan_Implementation_and_Enterprise_Customer_Integration_Resume_v2.docx'].map((name,i)=>`<article class="doc-row"><span class="file-mark">${i?'DOCX':'PDF'}</span><div><h3 class="filename">${name}</h3><small>${i===1?'Master · source for cover letters only':i===0?'Clinical Support · primary application resume':'Implementation · application resume'} · v${i===0?4:2}</small><small>Imported Oct 22 · ${i?42:186} KB</small></div>${btn('download','Save a copy')}<details><summary>Manage document</summary><p class="meta">Revising archives this version. Existing job selections and recorded applications keep their original document.</p><div class="actions">${btn('revision','Import revised version')}${btn('routing','Change role family')}${btn('archive','Archive')}${btn('master','Change master designation')}</div></details></article>`).join('')}<details><summary>Archived versions (1)</summary><p class="filename">Alex_Morgan_Clinical_Support_Resume_v3.pdf</p><p class="meta">Retained for previous selections and application history.</p>${btn('restore','Restore to active library')}</details>`)}
function candidate(){return heading('Candidate Profile','Review reusable contact and professional details.')+`<section class="profile">${notice(state==='missing'?'Profile not approved':'Current saved profile approved by you','Saving changed details requires a fresh approval choice. Approval enables mapping suggestions; sending information requires separate application authorization.','info')}<div class="fields">${field('first','First name','Alex')}${field('last','Last name','Morgan')}${field('email','Email','alex@example.test','email')}${field('phone','Phone (optional)','+1 202 555 0142')}${field('city','City (optional)','Ann Arbor')}${field('region','State / region (optional)','Michigan')}${field('country','Country (optional)','United States')}${field('linkedin','LinkedIn URL (optional)','')}<div class="field"><label for="pronouns">Pronouns (optional)</label><select id="pronouns"><option>Not specified</option><option>He/him</option><option>She/her</option><option>They/them</option></select></div></div><details><summary>Other professional links</summary><div class="fields">${field('github','GitHub URL (optional)')}${field('portfolio','Portfolio URL (optional)')}</div></details><label class="check"><input id="approve" type="checkbox">I have reviewed these facts and approve them for future mapping suggestions. This does not authorize transmission to an employer.</label><div class="form-actions">${btn('save-profile','Save profile','primary')}<span class="meta">Leave approval unchecked to save a draft.</span></div><p class="meta section">Work authorization, demographic questions, and employer consent remain on the employer form.</p></section>`}
function library(){return heading('Answer Library','Writing you chose to keep, with its original question and context.')+`<div class="field"><label for="library-search">Find previous writing</label><input id="library-search" type="search" placeholder="Try API incident or customer communication"></div>${state==='empty'?`<section class="empty"><h2>Your best answers can start here.</h2><p>After saving an application answer, choose “Save to Answer Library.” Each example is an independent copy.</p>${link('answers','Open application answers','button primary')}</section>`:`<article class="library-row" data-searchable><span class="eyebrow">Cedar Systems · Support Engineer</span><h3>Tell us about a challenging support incident.</h3><p>I compared request logs with deployment times and reproduced the issue in a test environment…</p><details><summary>Read and edit this library copy</summary><div class="field"><label for="library-answer">Saved answer</label><textarea id="library-answer">${esc(F.answer)}</textarea></div><p class="meta">Editing this copy does not change application history.</p>${btn('save-library','Save library copy')}</details><div class="actions">${btn('create-evidence','Create Career Evidence from this writing')}</div><p class="meta">Creates an independent draft with a source snapshot. You supply and review the facts.</p></article><article class="library-row" data-searchable><span class="eyebrow">Maple Harbor · Customer Reliability Engineer</span><h3>How do you explain a technical issue to a customer?</h3><p>I share the current findings, separate what we know from what we are investigating, and agree on the next update.</p><details><summary>Read complete example</summary><p class="source-text">I share the current findings, separate what we know from what we are investigating, and agree on the next update.</p></details></article>`}<p class="meta section">Use examples from “Help me answer” while writing. Inserting a starting point does not save or transfer it.</p>`}
function evidence(){return heading('Career Evidence','Experiences you can draw on when writing.',btn('new-evidence','Add experience','primary'))+`<p class="meta">Answer Library keeps previous wording. Career Evidence keeps the situation, your actions, and what happened.</p>${state==='empty'?`<section class="empty"><h2>Remember an example?</h2><p>Start an incomplete draft. Review it when it accurately describes your experience.</p>${btn('new-evidence','Add experience','primary')}</section>`:`<article class="library-row"><div class="section-head"><h3>Investigating intermittent API timeouts</h3>${status('Reviewed by you','good')}</div><p>Support Engineer · Cedar Systems · 2024</p><div class="row"><div><strong>What you did</strong><p>Compared logs, reproduced the issue, and coordinated findings with engineering.</p></div></div><p class="section">Outcome: <strong>Unknown</strong> · No long-term impact was measured.</p><details><summary>Edit this experience</summary>${evidenceForm()}</details></article><article class="library-row"><div class="section-head"><h3>Creating an incident handoff guide</h3>${status('Draft')}</div><p>Finish the situation and actions, then review. Drafts are excluded from AI evidence choices.</p>${btn('new-evidence','Continue draft')}</article>`}`}
function evidenceForm(){return `<div class="field"><label for="experience-title">Experience title</label><input id="experience-title" value="Investigating intermittent API timeouts"></div><div class="field section"><label for="situation">Situation</label><textarea id="situation" rows="3">A customer integration experienced intermittent timeouts.</textarea></div><div class="field"><label for="actions">Actions you took</label><textarea id="actions" rows="3">I compared logs and reproduced the issue in a test environment.</textarea></div><div class="field section"><label for="outcome">Outcome status</label><select id="outcome"><option>Unknown</option><option>Not recorded</option><option>Actual outcome recorded</option></select></div><label class="check"><input id="review-experience" type="checkbox">I confirm this accurately describes my experience. This is my review, not independent verification.</label><div class="form-actions">${btn('save-evidence','Save draft')}${btn('review-evidence','Mark as reviewed','primary')}</div>`}
function ai(){return heading('AI Connections','Optional help for answers and cover letters.')+notice('Writing remains available without AI','Readiness describes configuration at page load. It does not guarantee model access, allowance, or successful generation.','info')+[['Ollama','On this Mac','Checked at generation','Start Ollama and choose an installed model when drafting.'],['OpenAI API','External service · separate billing','Setup needed','Set OPENAI_API_KEY in the launch environment and restart YourMove.'],['ChatGPT via Codex','External service · subscription CLI','Setup needed','Install the vendor CLI and sign in separately.'],['Claude via Claude Code','External service · subscription CLI','Setup needed','Install the vendor CLI and sign in separately.'],['Anthropic API / OpenRouter','External services · separate billing','Setup needed','Set the corresponding API key in the launch environment and restart YourMove.'],['Compatible endpoint','Local or remote depends on configuration','Setup needed','Configure the full endpoint URL and credentials outside this screen.']].map(([n,t,s,d])=>`<article class="provider-row"><div><h3>${n}</h3><p>${t}</p></div>${status(s)}<details><summary>Setup and diagnostic information</summary><p>${d}</p><p class="meta">This screen does not store keys or start sign-in. Source review and generation authorization happen in the writing task.</p></details></article>`).join('')+`<p class="meta section">Connection testing and in-app credential management would require separate engineering. They are not simulated as existing features.</p>`}
function applications(){return heading('Applications','Your locally recorded submissions.')+`<p class="meta">These records are your confirmation of submission, not employer receipt confirmations.</p>${state==='empty'?`<section class="empty"><h2>No applications recorded yet</h2><p>Submit on the employer website, then record your confirmation from Prepare.</p>${link('opportunities','Open opportunities','button primary')}</section>`:`<article class="row"><div><div class="eyebrow">Maple Harbor Software</div><h3><a href="#history" data-job="3">Customer Reliability Engineer</a></h3><small>1 submission recorded · October 22, 2026</small></div>${link('history','View history →')}</article>`}`}
function history(){return jobHeader()+heading('Submission history','Recorded by you in YourMove.')+notice('Local record saved','YourMove did not submit this application or confirm employer receipt.','info')+`<ol class="timeline"><li><h3>Submission recorded</h3><time class="meta">October 22, 2026 · 10:42 AM</time><p>Resume: <span class="filename">${F.resume}</span></p><p>Notes: Confirmation page shown in employer browser.</p><p class="meta">The record retains the resume identity at recording. It does not establish employer acceptance of that file.</p></li></ol><div class="next-job"><div><div class="eyebrow">Continue your queue</div><h3>Implementation Engineer · Foster Bend</h3><p>Moving on closes this completed application’s managed browser.</p></div>${btn('next-job','Next job →','primary')}</div>`}
function utilities(){return heading('Utilities','Tools for imports, document matching, and inspection.')+[['Posting checks','Retrieve public details for saved URLs. Manual edits are preserved.','Check next 30 unchecked jobs'],['Role families','Literal title phrases suggest documents. Suggestions never change a saved selection.','Review matching rules'],['Discovered requirements','Observed question wording and provenance. Similar wording does not establish equivalence.','Review question inventory']].map(([t,d,b])=>`<section class="row"><div><h2>${t}</h2><p class="meta">${d}</p></div>${btn('utility',b)}</section>`).join('')+`<details open><summary>Recovery language study</summary>${notice('The selected resume could not be read','Choose an available copy. Previous application associations remain unchanged.')}${notice('New questions are available','Save or copy your unsaved text before refreshing the workbench.')}${notice('Generation could not finish','Your saved answer is unchanged. Review sources again before authorizing another attempt.')}</details>`}
function study(){return heading('Design review','Synthetic prototype · no production changes')+`<div class="compare-links">${['utility','editorial','focus'].map((d,i)=>`<a class="button" href="?direction=${d}#opportunities">${'ABC'[i]} · ${['Labeled workbench','Editorial workspace','Task focus'][i]}</a>`).join('')}<a class="button" href="compare.html">Side-by-side comparison</a></div><section class="study"><h2>State studies</h2><div class="compare-links">${[['opportunities','empty'],['prepare','missing'],['prepare','no-questions'],['prepare','active'],['prepare','partial'],['prepare','restart'],['answers','early'],['letter','no-letter'],['documents','empty'],['library','empty'],['evidence','empty']].map(([v,s])=>`<a class="button" href="?state=${s}#${v}">${v} · ${s}</a>`).join('')}</div><h2>Typography at actual application sizes</h2>${[12,14,16].map(n=>`<div class="type-sample"><small>${n}px / 400</small><div><p style="font-size:${n}px">System: Resume selected · Unsaved changes · Clinical Integrations</p><p class="jost" style="font-size:${n}px">Jost: Resume selected · Unsaved changes · Clinical Integrations</p></div></div>`).join('')}<div class="type-weights">${[300,400,500,600,700].map(w=>`<span style="font-weight:${w}">Jost ${w} · A considered next move.</span>`).join('')}</div><div class="type-sample"><small>Same width</small><div><p>${F.question}</p><p class="jost">${F.question}</p></div></div></section>`}
function render(){document.documentElement.dataset.theme=P.get('theme')||'light';document.body.dataset.direction=direction;document.body.classList.toggle('font-jost',P.get('font')==='selective');document.body.classList.toggle('font-all',P.get('font')==='all');const pages={opportunities,overview,prepare,answers,letter:coverLetter,transfer,documents,candidate,library,evidence,ai,applications,history,utilities,study};if(!pages[view])view='opportunities';$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#opportunities"><img class="normal" src="assets/yourmove-wordmark-primary.svg" alt="YourMove"><img class="reverse" src="assets/yourmove-wordmark-reverse.svg" alt="YourMove"></a>${navigation()}<div class="nav-bottom"><p class="meta">Local workspace</p></div></aside><div class="main"><header class="toolbar">${btn('navigation','☰ Navigation','nav-toggle')}${btn('focus','Hide sidebar','quiet hide-nav')}<span class="context">${jobViews.includes(view)?'Opportunities / '+esc(F.jobs[selectedJob].company):'YourMove'}</span><label>Appearance <select id="theme"><option value="light">Light</option><option value="dark">Dark</option></select></label></header><main id="content" class="content">${pages[view]()}</main><footer class="caption">Design prototype · synthetic data · ${link('study','Review directions and states')}</footer></div></div>`;$('#theme').value=document.documentElement.dataset.theme;if(view==='opportunities'&&state!=='empty')jobRows();if(view==='answers'){$('[data-action=previous]').disabled=question===0;$('[data-action=next]').disabled=question===3}bind();}
function announce(s){$('#announcement').textContent=s;}
function modal(title,body,actions=''){const m=$('#modal');m.innerHTML=`<h2>${title}</h2>${body}<div class="actions">${btn('close','Close')}${actions}</div>`;m.showModal();}
function navigate(v){location.hash=v;}
function bind(){$('#theme').onchange=e=>{P.set('theme',e.target.value);history.replaceState(null,'','?'+P+location.hash);document.documentElement.dataset.theme=e.target.value};['search','stage','sort'].forEach(id=>{if($('#'+id))$('#'+id).oninput=jobRows});if($('#question'))$('#question').onchange=e=>{if(dirty&&!confirm('Leave unsaved changes in this prototype? Cancel to save first.')){e.target.value=question;return}question=Number(e.target.value);answer=question>1?F.answer:'';dirty=false;render()};['answer','letter'].forEach(id=>{if($('#'+id))$('#'+id).oninput=e=>{if(id==='answer')answer=e.target.value;else letter=e.target.value;dirty=true;$('#save-status').textContent='Unsaved changes'}});if($('#library-search'))$('#library-search').oninput=e=>$$('[data-searchable]').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(e.target.value.toLowerCase()));}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]'), h=e.target.closest('[data-help]'),j=e.target.closest('[data-job]');if(j)selectedJob=Number(j.dataset.job);if(h){help=h.dataset.help;render();$('.help').open=true;return}if(!a)return;const act=a.dataset.action;if(act==='close'){$('#modal').close();return}if(act==='navigation'){modal('Navigation',`<nav class="modal-nav">${navigation()}</nav>`);return}if(act==='focus'){document.body.classList.toggle('hidden-nav');const hidden=document.body.classList.contains('hidden-nav');a.textContent=hidden?'Show navigation':'Hide sidebar';announce(hidden?'Sidebar hidden. Navigation remains in toolbar.':'Sidebar shown.');return}if(act==='clear'){$('#search').value='';$('#stage').value='active';jobRows();return}if(act==='bulk'){$('#job-list').classList.toggle('bulk-mode');modal('Bulk selection','<p>Production supports confirmed deletion only. Jobs with recorded submissions are excluded from bulk deletion. No bulk apply or automatic stage change is proposed.</p>');return}if(act==='add'){modal('Add opportunity',field('url','Job posting URL','https://example.test/jobs/1','url')+'<details><summary>Import multiple URLs</summary><textarea aria-label="One URL per line" placeholder="Up to 50 URLs"></textarea><p class="meta">Batch import saves URLs without fetching posting details.</p></details>',btn('demo-saved','Save opportunity','primary'));return}if(act==='record'){modal('Record completed application','<p>This saves your confirmation locally. It does not submit or verify employer receipt.</p>'+field('notes','Submission notes (optional)')+'<label class="check section"><input id="record-confirm" type="checkbox">I confirm that I submitted this application on the employer website.</label>',btn('confirm-record','Record completed application','primary'));return}if(act==='confirm-record'){if(!$('#record-confirm').checked){announce('Confirm employer-side submission first.');$('#record-confirm').focus();return}$('#modal').close();navigate('history');return}if(act==='save-answer'||act==='save-letter'){dirty=false;if(act==='save-answer')savedAnswer=answer;$('#save-status').textContent='Saved in this prototype session · not transferred';announce('Saved in prototype memory only.');return}if(act==='previous'||act==='next'){if(dirty&&!confirm('Leave unsaved changes in this prototype?'))return;question=Math.max(0,Math.min(3,question+(act==='next'?1:-1)));answer=question>1?F.answer:'';dirty=false;render();$('#prompt').scrollIntoView({block:'nearest'});return}if(act==='use-writing'||act==='adopt'){if(answer.trim()&&!confirm('Replace the current editor text with this starting point?'))return;answer=F.answer;dirty=true;$('#modal').close();render();$('.help').open=true;$('#answer').focus();return}if(act==='review-ai'){if(!$('#source-evidence').checked&&!$('#source-resume').checked){announce('Choose at least one factual source.');$('#source-evidence').focus();return}modal('Review generation sources',`<p>Provider: ${esc($('#provider').value)} · Model: ${esc($('#model').value)}</p><details open><summary>Exact synthetic payload</summary><p class="source-text">Question: ${F.question}\nSelected source: ${F.answer}</p></details><label class="check"><input id="authorize-ai" type="checkbox">I authorize one generation for this question, provider, model, and reviewed source payload.</label><label class="check"><input id="external-ai" type="checkbox">I acknowledge that this text may be transmitted to external model services.</label><p class="meta">This design simulation makes no provider call.</p>`,btn('generate-ai','Generate one draft','primary'));return}if(act==='generate-ai'){if(!$('#authorize-ai').checked||!$('#external-ai').checked){announce('Both authorizations are required.');return}$('#modal').innerHTML='<h2>Generating proposal…</h2><p>No provider call is made in this simulation.</p>';setTimeout(()=>{if(!$('#modal').open)return;$('#modal').innerHTML=`<h2>Generated proposal · not saved</h2><p class="source-text proposal">${F.answer}</p><p class="meta">Check every claim. Adoption leaves the text unsaved.</p><div class="actions">${btn('close','Discard preview')}${btn('adopt','Use as unsaved answer','primary')}</div>`},700);return}if(act==='new-evidence'||act==='create-evidence'){modal('Draft career experience',evidenceForm());return}if(act==='review-evidence'&&!$('#review-experience').checked){announce('Confirm your review first.');return}if(act==='generate-letter'&&!$('#letter-consent').checked){announce('Review and authorize generation first.');$('#letter-consent').focus();return}if(act==='transfer'){modal('Simulated transfer results',notice('One answer needs manual inspection','A field could not be verified. Other item outcomes remain independent.')+'<p>Contact fields observed as filled. Resume file selected; employer acceptance unverified. Submit personally on the employer site.</p>');return}if(act==='restart'){modal('Reopen employer application','<p>Reopening may lose browser-only work. Prior uploads will not be automatically replayed.</p><label class="check section"><input id="restart-confirm" type="checkbox">I understand reopening may lose browser-only work.</label>',btn('confirm-restart','Reopen application'));return}if(act==='confirm-restart'&&!$('#restart-confirm').checked){announce('Confirm the loss of browser-only work first.');return}if(act==='brief'){modal('Application brief · selectable fallback',`<p class="meta">Saved job details and question wording only. No answers, profile values, or editor text.</p><textarea readonly rows="12" aria-label="Application brief">${esc(F.jobs[selectedJob].title+'\n'+F.description+'\nQUESTIONS NEEDING MY INPUT\n'+F.question)}</textarea>`);return}if(act==='next-job'){selectedJob=5;$('#modal').close();navigate('prepare');return}if(act==='edit-job'){modal('Edit job and tracking',field('title','Job title',F.jobs[selectedJob].title)+field('company','Company',F.jobs[selectedJob].company)+'<p class="meta">Marked ready remains a manual planning label.</p>',btn('demo-saved','Save changes','primary'));return}modal('Prototype boundary',`<p><strong>${esc(a.textContent)}</strong> is represented for design review. No production file, database, browser, provider, or submission is changed.</p><p class="meta section">This interaction maps to an existing handler or a documented implementation increment. See the roadmap for acceptance requirements.</p>`);});
document.addEventListener('click',e=>{const l=e.target.closest('a[href^="#"]');if(!l)return;if(dirty&&l.hash!==location.hash&&!confirm('Leave unsaved edits? Cancel to save first.')){e.preventDefault();return}if($('#modal').open)$('#modal').close();});
window.addEventListener('hashchange',()=>{view=location.hash.slice(1);dirty=false;render();window.scrollTo(0,0);$('#content h1')?.focus({preventScroll:true})});render();
